WITH scored AS (SELECT *, FIRST_VALUE(page) IGNORE NULLS OVER w_grp AS first_known_page, SUM(duration_sec) OVER w_grp_2 AS cumulative_duration_sec, COUNT(duration_sec) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS duration_sec_count_90d, ROW_NUMBER() OVER (PARTITION BY page ORDER BY duration_sec DESC, id) AS row_seq, AVG(duration_sec) OVER w_hist AS duration_sec_avg_5 FROM web_events WINDOW w_grp AS (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp_2 AS (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_hist AS (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW)) SELECT id, event_type, event_time, first_known_page, cumulative_duration_sec, duration_sec_count_90d, row_seq, duration_sec_avg_5, CASE WHEN event_type RLIKE '^(purchase|click)$' THEN 'CORE' WHEN event_type RLIKE '^(page_view|add_to_cart)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS event_type_zone FROM scored ORDER BY duration_sec_avg_5 DESC NULLS LAST;
